ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soap http://schemas.xmlsoap.org/soap/envelope/
ns ns2 http://soap.sforce.com/schemas/class/IntegracionRemedy_ws
---
{
  soap#"Envelope": {
    soap#"Header": {
      "SessionHeader": {
        "sessionId": payload.Envelope.Body.loginResponse.result.sessionId
      }
    },
    soap#"Body": {
      ns2#"WsConsultaDetalle": {
        ns2#"MensajeEntrada": {
          ns2#"Id": vars.firstPayload.Envelope.Body.ConsultObjectDetailsSFInput.WsConsultaDetalle.MensajeEntrada.Id,
          ns2#"lstObjetosHijosRelacionados": vars.firstPayload.Envelope.Body.ConsultObjectDetailsSFInput.WsConsultaDetalle.MensajeEntrada.lstObjetosHijosRelacionados,
          ns2#"lstParametros": vars.firstPayload.Envelope.Body.ConsultObjectDetailsSFInput.WsConsultaDetalle.MensajeEntrada.lstObjetosHijosRelacionados.ObjetosHijosRelacionados.lstParametros,
          ns2#"NombreObjeto": vars.firstPayload.Envelope.Body.ConsultObjectDetailsSFInput.WsConsultaDetalle.MensajeEntrada.NombreObjeto
        }
      }
    }
  }
}

%dw 2.0
output application/json
---
{
  "ConsultObjectDetailsSFOutput": {
    "WSResponseHeader2": {
      "System": {
        "name": vars.vSystemName,
        "correlationID": correlationId,
        "processingServer": vars.vProcessingServer
      },
      "Service": {
        "status": "PASS",
        "responseDate": now()
      }
    },
"result": {
    "Id": payload.Envelope.Body.WsConsultaDetalleResponse.result.Id,
    "lstObjetosHijosRelacionados": payload.Envelope.Body.lstObjetosHijosRelacionados,
    "lstParametros": payload.Envelope.Body.WsConsultaDetalleResponse.result.lstParametros filterObject ((value, key) -> value.Campo != null) pluck ((item, index) -> {
 Keys:{Campo:(item.Campo),
 Valor: (item.Valor)
}
}

)
}}}

%dw 2.0
output application/json
---
{
  "Envelope": {
    "Body": {
      "ConsultObjectDetailsSFOutput": {
        "WSResponseHeader2": {
          "System": {
	        "name": vars.vSystemName,
	        "correlationID": correlationId,
	        "processingServer": vars.vProcessingServer
          },
          "Service": {
            "status": "FAIL",
            "responseDate": now(),
            "statusDetail": {
              "errorCode": "NOK",
              "errorMessage": ""
            }
          }
        }
      }
    }
  }
}
